<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {accountRequest} from '../accountAccess'
import DetailDialog from './DetailDialog.vue'
const props=defineProps<{base:string;token:string}>(),emit=defineEmits<{signout:[]}>()
type Device={id:string;label:string;current:boolean;active:boolean;created_at:string;expires_at:string;last_seen_at:string}
const items=ref<Device[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),selected=ref<Device|null>(null)
async function load(){busy.value=true;error.value='';try{const d=await accountRequest<{items:Device[];total:number}>(props.base,props.token,`/auth/sessions?page=${page.value}&page_size=6`);items.value=d.items;total.value=d.total}catch(e){error.value=e instanceof Error?e.message:'会话读取失败'}finally{busy.value=false}}
async function revoke(){if(!selected.value)return;busy.value=true;error.value='';const row=selected.value;try{await accountRequest(props.base,props.token,'/auth/sessions/'+row.id,undefined,'DELETE');selected.value=null;if(row.current)emit('signout');else await load()}catch(e){error.value=e instanceof Error?e.message:'结束会话失败，请刷新核对。'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="device-sessions"><h3>登录设备</h3><p>可结束不再使用的设备登录。</p><p v-if="busy" role="status"><span class="ui-spinner"/>正在读取…</p><p v-if="error" role="alert">{{error}} <button :disabled="busy" @click="load">重新读取</button></p><article v-for="d in items" :key="d.id"><div><strong>{{d.current?'当前设备':'设备会话'}} · {{d.active?'有效':'已结束'}}</strong><small>{{d.label}}</small><small>登录于 {{new Date(d.created_at).toLocaleString('zh-CN')}}</small></div><button v-if="d.active" :disabled="busy" @click="selected=d">结束登录</button></article><nav aria-label="登录设备分页"><span>共{{total}}条 · 第{{page}}页</span><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><button :disabled="busy||page*6>=total" @click="page++;load()">下一页</button></nav><DetailDialog v-if="selected" title="结束这个设备的登录？" size="small" :close-disabled="busy" @close="selected=null"><p>{{selected.current?'当前设备将退出，重新使用时需要登录。':'该设备后续访问将需要重新登录。'}}</p><p v-if="error" role="alert">{{error}}</p><template #footer><button :disabled="busy" @click="selected=null">保留登录</button><button :disabled="busy" @click="revoke">确认结束登录</button></template></DetailDialog></section></template>
<style scoped>.device-sessions article{display:flex;align-items:center;gap:12px;justify-content:space-between;border-bottom:1px solid #e1e7f0;padding:12px 0}.device-sessions article>div{min-width:0}.device-sessions small{display:block;overflow-wrap:anywhere;color:#73849d;font-size:11px;margin-top:6px}.device-sessions nav{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:12px}.device-sessions nav span{font-size:12px;margin-right:auto}.device-sessions button{font-size:12px;min-height:40px;flex-shrink:0}</style>
